import{_ as t,o,c as a,a0 as l}from"./chunks/framework.DbCRPtfr.js";const h=JSON.parse('{"title":"项目介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1791391065000}'),i={name:"guide/index.md"};function r(n,e,d,c,s,p){return o(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="项目介绍" tabindex="-1">项目介绍 <a class="header-anchor" href="#项目介绍" aria-label="Permalink to &quot;项目介绍&quot;">​</a></h1><p>electron-vite-template 是一个以 <strong>pnpm monorepo</strong> 组织的 Electron 桌面应用模板。技术栈：Electron + Vue 3 + Vite(rolldown 内核) + TypeScript 7，构建工具链基于 vite-plus（<code>vp</code>）。</p><div class="warning custom-block"><p class="custom-block-title">前置要求</p><p>阅读本文档默认您拥有 Vue 与 Node 基础知识。运行本项目需要：</p><ul><li><strong>Node.js ≥ 24</strong>（构建脚本使用 Node 原生 TypeScript 运行）</li><li><strong>pnpm ≥ 10</strong>（推荐直接使用 <code>corepack enable</code> 按 <code>packageManager</code> 字段对齐版本）</li></ul></div><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>Electron 模板市面不少，但大多数只提供&quot;能跑&quot;的起点。本模板把桌面应用工程里最容易烂尾的三件事做成了开箱即用的机制：</p><ol><li><strong>IPC 的类型安全</strong>——通道声明、主进程实现、渲染进程调用三端共享同一份合同，拼写错误和载荷不匹配都是编译错误（详见 <a href="/electron-vite-template/guide/ipc">IPC 合同系统</a>）；</li><li><strong>安全模型</strong>——全部窗口 <code>contextIsolation</code> + <code>sandbox</code>，渲染进程没有 Node 能力，与主进程的一切通信都经过 preload 白名单桥（详见 <a href="/electron-vite-template/guide/security">安全模型</a>）；</li><li><strong>源码保护的可选项</strong>——需要闭源交付时，一条命令把主进程编译成 V8 字节码，不需要时完全不感知（详见 <a href="/electron-vite-template/guide/bytecode">字节码保护</a>）。</li></ol><h2 id="功能一览" tabindex="-1">功能一览 <a class="header-anchor" href="#功能一览" aria-label="Permalink to &quot;功能一览&quot;">​</a></h2><ul><li>基于 electron-updater 的整包更新检查与安装</li><li>增量热更新（主进程 + 渲染进程内容，无需重新分发安装包）</li><li>域分组类型化 IPC（31 个内置通道，含窗口管理、文件下载、系统对话框、electron-store 封装等）</li><li>文件下载（含进度/完成/失败事件推送）</li><li>自定义标题栏（Windows 可关闭系统头部）</li><li>系统对话框、electron-store 持久化、托盘、多窗口（含浏览器/打印演示页）</li><li>vp run 缓存构建流水线、三平台 CI 工作流</li></ul><h2 id="分支说明" tabindex="-1">分支说明 <a class="header-anchor" href="#分支说明" aria-label="Permalink to &quot;分支说明&quot;">​</a></h2><ul><li><code>main</code>：唯一的开发与集成分支，变更直接提交或 PR 至此</li></ul>',10)])])}const m=t(i,[["render",r]]);export{h as __pageData,m as default};
